inline HttpAction http_action(int status) noexcept {
  if (status == 200) {
    return HttpAction::inspect_receipt;
  }
  if (status == 429 || (status >= 500 && status <= 599)) {
    return HttpAction::retry;
  }
  return HttpAction::stop;
}

struct Reply {
  enum ReplyKind : std::uint8_t { confirmed = 0, unconfirmed = 1, stopped = 2 };

  ReplyKind kind = unconfirmed;  // benign default: nothing known to be stored
  Receipt receipt{};
  std::chrono::milliseconds retry_after{0}; // minimum wait before another attempt
};

  if (reply.kind == Reply::confirmed && accepts(reply.receipt)) {
    receipt_ = reply.receipt;
    state_ = SubmissionState::confirmed;
    return SubmitStep::confirmed;
  }
  if (reply.kind == Reply::unconfirmed) {
    retry_after_ = reply.retry_after;
    return SubmitStep::unconfirmed;
  }
  // A bad receipt or stop signal ends automatic attempts, without asserting
  // that the server did not commit this operation.
  state_ = SubmissionState::stopped;
  return SubmitStep::stopped;
}

study_net::Reply operator()(const study_net::MatchRecord& record,
                            std::chrono::milliseconds phase_limit) const noexcept {
    using Reply = study_net::Reply;
    try {
        if (port_ < 1 || port_ > 65535 || phase_limit.count() <= 0)
            return {Reply::stopped, {}};
        httplib::Client client("127.0.0.1", port_);
        client.set_connection_timeout(phase_limit);
        client.set_read_timeout(phase_limit);
        client.set_write_timeout(phase_limit);
        const auto response = client.Post("/study/v1/matches",
            record_json(record).dump(), "application/json");
        if (!response) return {};

        case HttpAction::inspect_receipt:
            const auto receipt = parse_receipt(response->body);
            if (!receipt) return {Reply::stopped, {}};
            return {Reply::confirmed, *receipt};
        }
    } catch (const std::exception&) {
        // Local errors stop automatic work; never log a remote body here.
    }
    return {Reply::stopped, {}};
}

inline std::chrono::milliseconds retry_backoff(unsigned attempts) noexcept {
  if (attempts == 0) {
    return std::chrono::milliseconds{0};
  }
  if (attempts == 1) {
    return std::chrono::milliseconds{100};
  }
  return std::chrono::milliseconds{200};
}

inline std::optional<std::chrono::milliseconds> retry_after_seconds(
    const std::string& value) noexcept {
  if (value.empty()) {
    return std::nullopt;
  }
  for (char c : value) {
    if (c < '0' || c > '9') {
      return std::nullopt;
    }
  }

  std::uint64_t seconds = 0;
  const char* const first = value.data();
  const char* const last = first + value.size();
  const std::from_chars_result parsed = std::from_chars(first, last, seconds);
  if (parsed.ec != std::errc{} || parsed.ptr != last) {
    return std::nullopt;
  }

  using rep = std::chrono::milliseconds::rep;
  constexpr std::uint64_t kMaxSeconds =
      static_cast<std::uint64_t>(std::numeric_limits<rep>::max()) / 1000;
  if (seconds > kMaxSeconds) {
    return std::nullopt;
  }

  return std::chrono::milliseconds{static_cast<rep>(seconds) * 1000};
}

case HttpAction::retry: {
    std::chrono::milliseconds delay{0};
    const auto count = response->get_header_value_count("Retry-After");
    if (count > 1) return {Reply::stopped, {}};
    if (count == 1) {
        const auto hint = retry_after_seconds(response->get_header_value("Retry-After"));
        if (!hint) return {Reply::stopped, {}};
        delay = *hint;
    }
    return {Reply::unconfirmed, {}, delay};
}

const auto start = now();
for (;;) {
    if (submission.state() == State::empty) return RetryExit::no_request;
    if (submission.state() == State::confirmed) return RetryExit::confirmed;
    if (submission.state() == State::stopped) return RetryExit::stopped;
    if (submission.attempts() >= submission.max_attempts())
        return RetryExit::budget_exhausted;
    if (budget.count() <= 0) return RetryExit::budget_exhausted;
    auto left = budget - std::chrono::duration_cast<Millis>(now() - start);
    if (left.count() <= 0) return RetryExit::budget_exhausted;
    if (submission.attempts() != 0) {
        const auto delay = std::max(retry_backoff(submission.attempts()),
                                    submission.retry_after());
        // Do not shorten the server's minimum wait to fit our budget.
        if (delay >= left) return RetryExit::budget_exhausted;
        wait(delay);
        left = budget - std::chrono::duration_cast<Millis>(now() - start);
        if (left.count() <= 0) return RetryExit::budget_exhausted;
    }

        const auto phase_limit = std::min(left, Millis{2000});
        const auto step = submission.submit([&](const study_net::MatchRecord& r) noexcept {
            return sender(r, phase_limit);
        });
        if (step == Step::confirmed) return RetryExit::confirmed;
        if (step == Step::stopped) return RetryExit::stopped;
        // A started I/O call can finish after budget; its valid receipt still counts.
    }
}

