    Millis elapsed{0};
    std::vector<Millis> sleeps;
    auto now()const{return std::chrono::steady_clock::time_point{}+elapsed;}
    void wait(Millis delay){CHECK(delay.count()>=0);sleeps.push_back(delay);elapsed+=delay;}
};

